def sum_of_distances_in_tree(n, edges):
    g = [[] for _ in range(n)]
    for a, b in edges: g[a].append(b); g[b].append(a)
    order = []; parent = [-1] * n; st = [0]; seen = [False] * n; seen[0] = True
    while st:
        u = st.pop(); order.append(u)
        for v in g[u]:
            if not seen[v]: seen[v] = True; parent[v] = u; st.append(v)
    size = [1] * n; down = [0] * n
    for u in reversed(order):
        if parent[u] >= 0: size[parent[u]] += size[u]; down[parent[u]] += down[u] + size[u]
    ans = [0] * n; ans[0] = down[0]
    for u in order:
        if parent[u] >= 0: ans[u] = ans[parent[u]] - size[u] + (n - size[u])
    return ans

