vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& e) {
    vector<vector<int>> g(n); for (auto& x : e) { g[x[0]].push_back(x[1]); g[x[1]].push_back(x[0]); }
    vector<int> order, par(n, -1), st{0}; vector<char> seen(n, 0); seen[0] = 1;
    while (!st.empty()) { int u = st.back(); st.pop_back(); order.push_back(u); for (int v : g[u]) if (!seen[v]) { seen[v] = 1; par[v] = u; st.push_back(v); } }
    vector<long long> sz(n, 1), down(n, 0), ans(n, 0);
    for (int i = n - 1; i >= 0; i--) { int u = order[i]; if (par[u] >= 0) { sz[par[u]] += sz[u]; down[par[u]] += down[u] + sz[u]; } }
    ans[0] = down[0]; for (int u : order) if (par[u] >= 0) ans[u] = ans[par[u]] - sz[u] + (n - sz[u]);
    return vector<int>(ans.begin(), ans.end());
}
